mapper.select:
select bid.id, bid.device_name, bid.space_id, bid.create_time, bid.enable_status FROM bbx_ioc_device bid
and bid.deleted = 1
and bid.tenant_id = #{condition.tenantId}
AND bid.device_name like CONCAT('%',#{condition.deviceName},'%')
AND bid.space_id = #{condition.spaceId}
AND bid.enable_status = #{condition.enableStatus}
AND bid.id in(select device_id from bbx_device_label_rel where label_id = #{condition.labelId})
AND bid.id not in(select device_id from bbx_device_label_rel where label_id = #{condition.noLabelId})
order by bid.create_time DESC
